namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)));
        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-5)));
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Returns notifications added after the given ID (exclusive).
    /// </summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulates an external system pushing new notifications over time.
    /// Called by a background hosted service.
    /// </summary>
    public void AddRandom()
    {
        string[] templates =
        [
            "Server health check passed.",
            "New comment on your post.",
            "Deployment succeeded.",
            "Disk usage warning: 85%.",
            "User signed up.",
            "Backup completed.",
            "Payment received.",
        ];

        var message = templates[Random.Shared.Next(templates.Length)];

        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }
}

/// <summary>
/// Periodically adds fake notifications so polling has something to find.
/// </summary>
public class NotificationGeneratorService : BackgroundService
{
    private readonly NotificationService _notifications;

    public NotificationGeneratorService(NotificationService notifications)
    {
        _notifications = notifications;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            _notifications.AddRandom();
        }
    }
}

@page "/notifications"
@using NotificationsApp.Services
@rendermode InteractiveServer
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during SSR *and* when the component re-initializes on the
    // interactive circuit. PersistentComponentState would be the textbook
    // way to avoid a second fetch, but since our data source is an
    // in-process singleton the cost is negligible and the result is
    // identical — so a simple GetAll() is the pragmatic choice here.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
    }

    // Only fires once the component is truly interactive (not during SSR).
    // Safe place to start the long-running polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var lastId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = NotificationSvc.GetSince(lastId);

            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

