+
+public record Notification(int Id, string Message, DateTime Timestamp);
+
+public class NotificationService
+{
+    private int _nextId = 1;
+    private readonly List<Notification> _notifications = new();
+    private readonly Lock _lock = new();
+
+    public NotificationService()
+    {
+        // Seed with initial fake data
+        _notifications.Add(new Notification(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)));
+        _notifications.Add(new Notification(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)));
+        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-5)));
+    }
+
+    public List<Notification> GetAll()
+    {
+        lock (_lock)
+        {
+            return _notifications.ToList();
+        }
+    }
+
+    /// <summary>
+    /// Returns notifications added after the given ID (exclusive).
+    /// </summary>
+    public List<Notification> GetSince(int lastSeenId)
+    {
+        lock (_lock)
+        {
+            return _notifications.Where(n => n.Id > lastSeenId).ToList();
+        }
+    }
+
+    /// <summary>
+    /// Simulates an external system pushing new notifications over time.
+    /// Called by a background hosted service.
+    /// </summary>
+    public void AddRandom()
+    {
+        string[] templates =
+        [
+            "Server health check passed.",
+            "New comment on your post.",
+            "Deployment succeeded.",
+            "Disk usage warning: 85%.",
+            "User signed up.",
+            "Backup completed.",
+            "Payment received.",
+        ];
+
+        var message = templates[Random.Shared.Next(templates.Length)];
+
+        lock (_lock)
+        {
+            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
+        }
+    }
+}
+
+/// <summary>
+/// Periodically adds fake notifications so polling has something to find.
+/// </summary>
+public class NotificationGeneratorService : BackgroundService
+{
+    private readonly NotificationService _notifications;
+
+    public NotificationGeneratorService(NotificationService notifications)
+    {
+        _notifications = notifications;
+    }
+
+    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
+    {
+        while (!stoppingToken.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
+            _notifications.AddRandom();
+        }
+    }
+}
